package au.edu.oshc.smartguide; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/scenarios") class ScenarioController{@GetMapping List<Map<String,Object>> all(){return List.of(x("unwell","Feeling unwell","First time feeling sick","You feel unwell, but it does not appear to be an emergency.","What should you consider first?",List.of("An appropriate non-emergency healthcare option such as a GP","Always go directly to an emergency department","Ignore the problem","Wait until severe"),0,"The brief highlights recognising an appropriate GP/non-emergency pathway rather than going straight to hospital.","Use current authoritative guidance if unsure."),x("medicine","Need medication","First medication experience","You need medication after speaking with a healthcare professional.","What role should you understand?",List.of("The role of a pharmacy and medication process","Hospitals are the only place for medicine","Every medicine is free","Claims never matter"),0,"The brief identifies understanding the pharmacy role as an important practical outcome.","Do not assume medicine is free or covered."),x("bill","Medical bill","First bill","You receive a medical bill and are unsure what you may need to pay.","What is important to understand?",List.of("There may be out-of-pocket costs and a claim may be possible depending on circumstances","Every bill is paid in full","Bills never matter","A bill always means cover is invalid"),0,"The brief highlights out-of-pocket costs and possible claims.","Check current product information."),x("claim","Need to claim","First claim","You paid a medical expense and want to understand whether a claim may be appropriate.","What should you learn?",List.of("The basic claim process and possible documentation","Claims are never possible","No information is required","All claims are guaranteed"),0,"The brief identifies claim steps and documentation as a knowledge gap.","Use current official claim guidance."),x("emergency","Urgent or emergency","First urgent situation","You believe your situation may be urgent or an emergency.","What is the learning objective?",List.of("Recognise urgency and know what steps to take using appropriate emergency support","Treat every illness as an emergency","Ignore it","Wait for a claim"),0,"The brief explicitly calls for awareness of steps for urgent/emergency situations.","This prototype does not replace emergency services or medical advice."));}
Map<String,Object>x(String id,String title,String moment,String sit,String q,List<String>o,int c,String ex,String rem){return Map.of("id",id,"title",title,"moment",moment,"situation",sit,"question",q,"options",o,"correctIndex",c,"explanation",ex,"reminder",rem);}}
